@page "/apply"
@rendermode InteractiveServer
@using sv_f19570f4743e4230bef2106f068dc0da.Services
@using sv_f19570f4743e4230bef2106f068dc0da.Components.Pages.Apply
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@personalFullName" Email="@personalEmail"
                              Phone="@personalPhone" Address="@personalAddress"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="HandlePersonalNext" />
            break;
        case 1:
            <WorkHistoryStep Entries="@workEntries" OnNext="HandleWorkNext" OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep References="@references" OnNext="HandleReferencesNext" OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@coverLetter" OnNext="HandleCoverLetterNext" OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep Personal="@personalResult!" WorkEntries="@workEntries" References="@references"
                        CoverLetter="@coverLetter" OnEditStep="GoToStep" OnBack="GoBack"
                        SubmitApplication="SubmitAsync" />
            break;
    }
</div>

@code {
    private int currentStep;
    private int highestCompletedStep = -1;

    // Step 1 state
    private string personalFullName = "";
    private string personalEmail = "";
    private string personalPhone = "";
    private string personalAddress = "";
    private PersonalInfoStep.PersonalInfoResult? personalResult;

    // Step 2 state
    private List<WorkEntryForm.WorkEntryModel> workEntries = new()
    {
        new("", "", DateTime.Today, null, "", false)
    };

    // Step 3 state
    private List<ReferenceForm.ReferenceModel> references = new()
    {
        new("", "", "", ""),
        new("", "", "", "")
    };

    // Step 4 state
    private string coverLetter = "";

    private void HandlePersonalNext(PersonalInfoStep.PersonalInfoResult result)
    {
        personalResult = result;
        personalFullName = result.FullName;
        personalEmail = result.Email;
        personalPhone = result.Phone;
        personalAddress = result.Address;
        AdvanceTo(1);
    }

    private void HandleWorkNext(List<WorkEntryForm.WorkEntryModel> entries)
    {
        workEntries = entries;
        AdvanceTo(2);
    }

    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> refs)
    {
        references = refs;
        AdvanceTo(3);
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        AdvanceTo(4);
    }

    private void AdvanceTo(int step)
    {
        if (currentStep > highestCompletedStep)
            highestCompletedStep = currentStep;
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void GoToStep(int step)
    {
        if (step <= highestCompletedStep)
            currentStep = step;
    }

    private async Task<int> SubmitAsync()
    {
        var workHistory = new WorkHistory(workEntries.Select(e =>
            new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList());

        var refs = references.Select(r =>
            new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

        var application = new JobApplication(
            new PersonalInfo(personalResult!.FullName, personalResult.Email, personalResult.Phone, personalResult.Address),
            workHistory, refs, coverLetter);

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.apply-container {
    max-width: 720px;
    margin: 2rem auto;
    padding: 0 1rem;
}

/* Step Indicator */
.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem;
    gap: 0.25rem;
}

.step-item {
    flex: 1;
    text-align: center;
    padding: 0.75rem 0.5rem;
    border-bottom: 3px solid #ddd;
    transition: border-color 0.2s;
}

.step-item.active {
    border-color: #0d6efd;
    font-weight: 600;
}

.step-item.completed {
    border-color: #198754;
}

.step-item.dimmed {
    opacity: 0.5;
}

.step-button {
    background: none;
    border: none;
    cursor: pointer;
    font: inherit;
    color: inherit;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.25rem;
    width: 100%;
}

.step-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.75rem;
    height: 1.75rem;
    border-radius: 50%;
    background: #e9ecef;
    font-size: 0.85rem;
}

.step-item.active .step-icon {
    background: #0d6efd;
    color: white;
}

.step-item.completed .step-icon {
    background: #198754;
    color: white;
}

.step-label {
    font-size: 0.8rem;
}

/* Form elements */
.step-section {
    margin-bottom: 2rem;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font: inherit;
}

.form-group textarea {
    resize: vertical;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.4rem;
    font-weight: normal !important;
    margin-top: 0.4rem;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn-primary {
    padding: 0.5rem 1.5rem;
    background: #0d6efd;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font: inherit;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-secondary {
    padding: 0.5rem 1.5rem;
    background: #6c757d;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font: inherit;
}

.btn-danger {
    padding: 0.35rem 1rem;
    background: #dc3545;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-link {
    background: none;
    border: none;
    color: #0d6efd;
    cursor: pointer;
    font-size: 0.85rem;
    text-decoration: underline;
}

/* Fieldsets */
fieldset {
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 1rem;
    margin-bottom: 1rem;
}

fieldset legend {
    font-weight: 600;
    padding: 0 0.5rem;
}

/* Character count */
.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.25rem;
}

/* Review */
.review-section {
    margin-bottom: 1.5rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid #dee2e6;
}

.review-section h3 {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
}

.review-section dt {
    font-weight: 500;
}

.review-entry {
    margin: 0.5rem 0;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 4px;
}

/* Error & confirmation */
.error-message {
    color: #dc3545;
    background: #f8d7da;
    border: 1px solid #f5c2c7;
    padding: 0.75rem;
    border-radius: 4px;
    margin-top: 1rem;
}

.confirmation {
    text-align: center;
    padding: 2rem;
    background: #d1e7dd;
    border: 1px solid #badbcc;
    border-radius: 6px;
}

.confirmation h3 {
    color: #0f5132;
}

