.step-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.75rem;
    height: 1.75rem;
    border-radius: 50%;
    background: #e9ecef;
    font-size: 0.85rem;
}

.step-item.active .step-icon {
    background: #0d6efd;
    color: white;
}

.step-item.completed .step-icon {
    background: #198754;
    color: white;
}

.step-label {
    font-size: 0.8rem;
}

