 @namespace sv_f19570f4743e4230bef2106f068dc0da.Components.Pages.Apply

 <fieldset class="work-entry">
     <legend>Position @(Index + 1)</legend>

     <div class="form-group">
         <label>Company *</label>
         <input type="text" value="@Entry.Company" @onchange="e => Update(Entry with { Company = (string?)e.Value ?? "" })" />
     </div>

     <div class="form-group">
         <label>Job Title *</label>
         <input type="text" value="@Entry.Title" @onchange="e => Update(Entry with { Title = (string?)e.Value ?? "" })" />
     </div>

     <div class="form-row">
         <div class="form-group">
             <label>Start Date *</label>
             <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="e => Update(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? "") })" />
         </div>

         <div class="form-group">
             <label>End Date</label>
             <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")" disabled="@IsCurrent"
                    @onchange="e => Update(Entry with { EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value) })" />
             <label class="checkbox-label">
                 <input type="checkbox" checked="@IsCurrent" @onchange="HandleCurrentToggle" />
                 Current position
             </label>
         </div>
     </div>

     <div class="form-group">
         <label>Description</label>
         <textarea value="@Entry.Description" @onchange="e => Update(Entry with { Description = (string?)e.Value ?? "" })"></textarea>
     </div>

     @if (CanRemove)
     {
         <button type="button" class="btn-danger" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
     }
 </fieldset>

 @code {
     [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
     [Parameter] public int Index { get; set; }
     [Parameter] public bool CanRemove { get; set; }
     [Parameter, EditorRequired] public EventCallback<WorkEntryModel> OnChanged { get; set; }
     [Parameter] public EventCallback OnRemove { get; set; }

     private bool IsCurrent => Entry.EndDate is null && Entry.IsCurrent;

     private async Task Update(WorkEntryModel updated) => await OnChanged.InvokeAsync(updated);

     private async Task HandleCurrentToggle(ChangeEventArgs e)
     {
         var isCurrent = (bool)(e.Value ?? false);
         await OnChanged.InvokeAsync(Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate });
     }

     public record WorkEntryModel(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description, bool IsCurrent);
 }

