        OnChanged.InvokeAsync(Entry with { Title = (string?)e.Value ?? "" });

    private Task UpdateStartDate(ChangeEventArgs e) =>
        OnChanged.InvokeAsync(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? DateTime.Today.ToString("yyyy-MM-dd")) });

